import { Card, CardSection } from "./card";

// a settings block: two rows divided by a rule, Save in the footer
<Card title="Notifications" description="Where we reach you about orders." titleAs="h2"
  footer={<Button size="sm" label="Save" loading={saving} onClick={save} />}>
  <CardSection title="Order emails" description="A receipt and shipping updates."
    actions={<Switch showRow={false} aria-label="Order emails" checked={emails} onChange={setEmails} />} />
  <CardSection title="Text messages" description="Only when a courier is on the way."
    actions={<Switch showRow={false} aria-label="Text messages" checked={sms} onChange={setSms} />} />
</Card>

// the whole card is one link; the Pause button inside still works on its own
<Card icon="calendar" eyebrow="Subscription" title="Coffee, every 2 weeks" description={`Next box ${nextDate}`}
  href="/subscriptions/42" actions={<Button size="sm" variant="ghost" label="Pause" onClick={pause} />} />

// folds; the parent owns the state
<Card title="Delivery notes" collapsible open={notesOpen} onOpenChange={setNotesOpen}>{notes}</Card>

// parts form, for a custom header and a table that runs edge to edge
<Card>
  <CardHeader title="Invoices" actions={<Button size="sm" variant="secondary" label="Export" />} />
  <CardBody flush><table>…</table></CardBody>
  <CardFooter align="between"><span>{count} invoices</span><Pagination … /></CardFooter>
</Card>
